# Extracts the LALR tables of jq 1.7.1's bison parser (src/parser.c, generated by bison 3.8.2
# from src/parser.y, MIT license) into jq/bisontab.vu, so vjq can replay bison's syntax error
# handling (its messages and its error recovery) exactly.
#   python3 gen_bison.py JQ_SRC/src/parser.c > ../bisontab.vu
import re, sys

src = open(sys.argv[1]).read()

def table(name):
    m = re.search(r"static const \w+ " + name + r"\[\] =\s*\{(.*?)\};", src, re.S)
    return [int(x) for x in m.group(1).replace("\n", " ").split(",") if x.strip()]

def define(name):
    return int(re.search(r"#define " + name + r"\s+\(?(-?\d+)\)?", src).group(1))

names = re.search(r"yytname\[\] =\s*\{(.*?)YY_NULLPTR", src, re.S).group(1)
names = re.findall(r'"((?:[^"\\]|\\.)*)"', names)
names = [n.encode().decode("unicode_escape") for n in names]

def tnamerr(s):
    # bison's yytnamerr: strip the double quotes unless the name has ' , or a lone backslash
    if s.startswith('"'):
        out = ""
        i = 1
        while True:
            c = s[i]
            if c in "',": return s
            if c == "\\":
                i += 1
                if s[i] != "\\": return s
                out += "\\"
            elif c == '"':
                return out
            else:
                out += c
            i += 1
    return s

rules = {}
for m in re.finditer(r"case (\d+): /\* (.*?)  \*/", src):
    rules[m.group(2)] = int(m.group(1))

def rule(text):
    return rules[text]

def vu_ints(name, xs):
    return f'const {name} = "{",".join(str(x) for x in xs)}"\n'

def vu_str(s):
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("{", "{{").replace("}", "}}")

out = ["# Generated by tools/gen_bison.py from jq 1.7.1's src/parser.c (bison 3.8.2; jq is MIT\n",
       "# licensed, Copyright (C) 2012 Stephen Dolan). Do not edit.\n\n"]
for d in ["YYFINAL", "YYLAST", "YYNTOKENS", "YYPACT_NINF", "YYTABLE_NINF"]:
    out.append(f"const {d} = {define(d)}\n")
for t in ["yypact", "yydefact", "yypgoto", "yydefgoto", "yytable", "yycheck", "yyr1", "yyr2"]:
    out.append(vu_ints(t.upper(), table(t)))
ntok = define("YYNTOKENS")
out.append('const TNAMES = "' + "\\t".join(vu_str(tnamerr(n)) for n in names[:ntok]) + '"   # split on tabs\n')
named = {
    "R_MODULE": 'Module: "module" Exp \';\'',
    "R_IF_ERR": 'Exp: "if" Exp "then" error',
    "R_TRY_ERR": 'Exp: "try" Exp "catch" error',
    "R_IMPORT_META": "Import: ImportWhat Exp ';'",
    "R_IMPORT_FROM": "ImportFrom: String",
    "R_STR_FMT": "StringStart: FORMAT QQSTRING_START",
    "R_STR": "String: StringStart QQString QQSTRING_END",
    "R_QQ_EMPTY": "QQString: %empty",
    "R_QQ_TEXT": "QQString: QQString QQSTRING_TEXT",
    "R_QQ_INTERP": "QQString: QQString QQSTRING_INTERP_START Exp QQSTRING_INTERP_END",
    "R_BREAK_ERR": 'Term: "break" error',
    "R_DOT_ERR": "Term: '.' error",
    "R_DOT_IDENT_ERR": "Term: '.' IDENT error",
    "R_OBJPAT_KEY": "ObjPat: '(' Exp ')' ':' Pattern",
    "R_OBJPAT_ERR": "ObjPat: error ':' Pattern",
    "R_DICT_KEY": "MkDictPair: '(' Exp ')' ':' ExpD",
    "R_DICT_ERR": "MkDictPair: error ':' ExpD",
    "R_TERM_LIT": "Term: LITERAL",
    "R_TERM_STR": "Term: String",
    "R_TERM_PAREN": "Term: '(' Exp ')'",
    "R_EXP_TERM": "Exp: Term",
}
for k, v in named.items():
    out.append(f"const {k} = {rule(v)}\n")
sys.stdout.write("".join(out))
